// 严格与后端 PublishedNote 映射的数据接口定义
export interface PublishedNoteItem {
  id: string;
  title: string;
  // 🌟 2. 动态复用全局 NoteType（现在它已经是 note | post | wiki...），完美消灭 'thought' 遗毒
