  type: 'occupation'
  rank?: '初级' | '中级' | '高级' | '大师' | '传说'
  requirements?: string
  abilities?: string[]
  equipment?: string[]
  affiliation?: string
  advancement?: string[]
}

// 3.8 组织卡片
export interface OrganizationData extends BaseCardData {
  type: 'organization'
  purpose?: string
  headquarters?: string
  foundedDate?: string
  size?: '小型' | '中型' | '大型' | '巨型'
}

// 3.9 生物卡片
export interface CreatureData extends BaseCardData {
  type: 'creature'
  habitat?: string
  diet?: string
  temperament?: string
  abilities?: string[]
  threatLevel?: '低' | '中' | '高' | '极度危险'
}

// 3.10 技能卡片
export interface SkillData extends BaseCardData {
  type: 'skill'
  skillType?: '主动' | '被动' | '终极' | '天赋'
  cost?: string
  cooldown?: string
  effect?: string
  prerequisite?: string
  level?: number
}

// 3.11 气候卡片
export interface ClimateData extends BaseCardData {
  type: 'climate'
  climateName: string
  alternativeNames?: string[]
  manifestations: string[]
  frequency: string
  predictability: string
  cause: string
  effects: string[]
  aftermath: string[]
  countermeasures: string[]
  safeZones?: string
}

// ✅ 3.12 概念卡片（抽象设定）
export interface ConceptData extends BaseCardData {
  type: 'concept'
  // 所有字段通过自定义属性 + 内容块扩展
