  desc: string;
  cover: string;
  completedRate: number;
  days: number;
  createdAt: number;
}

export interface RecordItem {
  day: number;
  isCompleted: boolean;
  isLate: boolean;
  text: string;
  image: string;
}

export interface Member {
  id: number;
  name: string;
  active: boolean;
  records: RecordItem[];
}

export interface Post {
  id: number;
  author: string;
  content: string;
  createdAt: number;
  replies: Reply[];
}

export interface Reply {
  id: number;
