// src/composables/世界观管理/useCardForm.ts
import { ref } from 'vue'
import { type CardType } from '@/views/世界观管理/card_type'
import type { AttributeItem } from '@/views/世界观管理/card_type'

function createEmptyCardForm() {
  return {
    title: '',
    type: 'character' as CardType,
    coverImage: '',
    galleryImages: [] as string[],
    attributes: [] as AttributeItem[],
    description: '',
    content: {} as Record<string, any>,   // ✅ 对象
    tags: [] as string[],
    relations: [] as { targetCardId: string; relationType: string }[],
    contentBlocks: [] as {
      id: string;
      cardId: string;
      cardType: string;
      order: number;
      cardTitle?: string;
      cardCover?: string;
      cardSummary?: string;
      cardAttributes?: { key: string; value: string }[];
      contextLabel?: string;
    }[],
  }
}

export type CardForm = ReturnType<typeof createEmptyCardForm>

export function useCardForm() {
  const form = ref(createEmptyCardForm())
  const resetForm = () => { form.value = createEmptyCardForm() }

  // 批量设置表单数据（用于加载已有卡片）
  const setFormData = (data: Partial<typeof form.value>) => {
    Object.assign(form.value, data)
  }

  return {
    form,
    resetForm,
    setFormData,
  }
}

import { onScopeDispose, ref, toValue, watch, type MaybeRefOrGetter } from 'vue'
import { useWorldStore } from '@/stores/world'

/** 后台详情加载统一复用 Store 缓存，切换项目或卸载后停止后续批次。 */
export function useCardPreload(projectId: MaybeRefOrGetter<string | undefined>,
  cardIds?: MaybeRefOrGetter<string[]>) {
  const store = useWorldStore()
  const loading = ref(false)
  let version = 0
  let disposed = false

  async function load(ids: string[]) {
    const current = ++version
    const pid = toValue(projectId)
    loading.value = false
    if (disposed || !pid) return
    const missing = [...new Set(ids)].filter(id => id && !store.getCardDetailById(id, pid))
    loading.value = missing.length > 0
    try {
      for (let offset = 0; offset < missing.length; offset += 8) {
        if (disposed || current !== version || pid !== toValue(projectId)) return
        await Promise.all(missing.slice(offset, offset + 8).map(id => store.loadCardDetail(pid, id).catch(error => {
          console.warn(`加载卡片详情失败: ${id}`, error)
        })))
      }
    } finally {
      if (current === version) loading.value = false
    }
  }

  if (cardIds) watch([() => toValue(projectId), () => JSON.stringify(toValue(cardIds))],
    () => { void load(toValue(cardIds)) }, { immediate: true })
  onScopeDispose(() => { disposed = true; version++; loading.value = false })
  return { loading, load, getDetail: (id: string) => store.getCardDetailById(id, toValue(projectId)) ?? null }
}

